CREATE COLUMN TABLE "TEST_AP"."@RA_TAB" ("Code" NVARCHAR(50) NOT NULL , "Name" NVARCHAR(100) NOT NULL , "U_MenuUID" NVARCHAR(50), "U_ItemId" NVARCHAR(50), "U_Caption" NVARCHAR(50), "U_Active" NVARCHAR(50) DEFAULT 'Y', "U_MenuCaption" NVARCHAR(50), "U_Execute" NVARCHAR(50) DEFAULT '1', PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "KRA_TAB_NAME" ON "TEST_AP"."@RA_TAB" ( "Name" ASC )